package cn.local.rainreminder;
import android.appwidget.*;import android.content.*;import android.graphics.*;import android.text.*;import android.view.View;import android.widget.RemoteViews;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;

/** Fixed readable period heights; only the body scrolls, while the seven dates stay visible. */
final class WidgetWeekTable {
 static final int ROW_HEIGHT=46;
 static List<RemoteViews> rows(Context c,LocalDate monday,int width,long now){Bitmap whole=draw(c,monday,width,false,now);List<RemoteViews> out=new ArrayList<>();int periods=ImportActivity.parseTimes(ImportActivity.periodTimes(c)).size();float scale=whole.getWidth()/(float)width;for(int first=0;first<periods;first+=2){int top=Math.round(first*ROW_HEIGHT*scale),bottom=Math.min(whole.getHeight(),Math.round(Math.min(periods,first+2)*ROW_HEIGHT*scale));Bitmap part=Bitmap.createBitmap(whole.getWidth(),Math.max(1,bottom-top),Bitmap.Config.ARGB_8888);part.setDensity(whole.getDensity());new Canvas(part).drawBitmap(whole,0,-top,null);RemoteViews row=new RemoteViews(c.getPackageName(),R.layout.rain_widget_week_body_v32);row.setImageViewBitmap(R.id.widget_day_card_grid,part);row.setContentDescription(R.id.widget_day_card_grid,"第"+(first+1)+"至"+Math.min(periods,first+2)+"节；"+description(c,monday,now));out.add(row);}whole.recycle();return out;}
 static final class Inline {static void bind(Context c,RemoteViews views,LocalDate monday,int width,long now){RemoteViews.RemoteCollectionItems.Builder items=new RemoteViews.RemoteCollectionItems.Builder().setViewTypeCount(1).setHasStableIds(false);List<RemoteViews> rows=rows(c,monday,width,now);for(int n=0;n<rows.size();n++)items.addItem(n,rows.get(n));views.setRemoteAdapter(R.id.widget_day_pages,items.build());}}
 static List<WeekTable.Item> items(Context c,LocalDate monday,long now){List<WeekTable.Item> out=new ArrayList<>();for(WeekTable.Item item:WeekTable.occurrences(Agenda.all(c),monday))if(item.end>now)out.add(item);return out;}
 static LocalDate monday(Context c,int id,long now){LocalDate date=WidgetOptions.date(c,id,now);return date.minusDays(date.getDayOfWeek().getValue()-1);}
 static void bind(Context c,RemoteViews views,int id,int height,long now){LocalDate monday=monday(c,id,now);int width=Math.max(220,Math.min(900,AppWidgetManager.getInstance(c).getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,300)-20));views.setTextViewText(R.id.widget_heading,"周课表");views.setViewVisibility(R.id.widget_rows,View.GONE);views.setViewVisibility(R.id.widget_primary_list,View.GONE);views.setViewVisibility(R.id.widget_date,View.GONE);views.setViewVisibility(R.id.widget_week_header,View.VISIBLE);views.setImageViewBitmap(R.id.widget_week_header,draw(c,monday,width,true,now));views.setViewVisibility(R.id.widget_day_pages,View.VISIBLE);Intent data=new Intent(c,WidgetDayService.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).putExtra("day",monday.toEpochDay()).putExtra("width",width).setData(android.net.Uri.parse("rainwidget://week/v32/"+id+"/"+monday+"/"+width));if(android.os.Build.VERSION.SDK_INT>=31)Inline.bind(c,views,monday,width,now);else views.setRemoteAdapter(R.id.widget_day_pages,data);views.setContentDescription(R.id.widget_week_header,monday+"至"+monday.plusDays(6)+"，周一到周日");}
 static Bitmap draw(Context c,LocalDate monday,int width,boolean header,long now){List<LocalTime[]> periods=ImportActivity.parseTimes(ImportActivity.periodTimes(c));int height=header?38:ROW_HEIGHT*periods.size();float scale=Math.min(2,c.getResources().getDisplayMetrics().density);Bitmap bitmap=Bitmap.createBitmap(Math.max(1,Math.round(width*scale)),Math.round(height*scale),Bitmap.Config.ARGB_8888);bitmap.setDensity(Math.round(160*scale));Canvas canvas=new Canvas(bitmap);canvas.scale(scale,scale);canvas.drawColor(0xFFF8FAF9);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setTypeface(c.getResources().getFont(R.font.ui));float axis=32,col=(width-axis)/7f;LocalDate today=Instant.ofEpochMilli(now).atZone(ZoneId.systemDefault()).toLocalDate();
  if(header){p.setTextAlign(Paint.Align.CENTER);p.setColor(Ui.MUTED);p.setTextSize(8);canvas.drawText("时间",axis/2,23,p);String[] names={"一","二","三","四","五","六","日"};for(int day=0;day<7;day++){LocalDate date=monday.plusDays(day);float x=axis+day*col;if(date.equals(today)){p.setColor(0xFFDDEDE7);canvas.drawRoundRect(new RectF(x+1,1,x+col-1,37),5,5,p);}p.setColor(date.equals(today)?Ui.GREEN:Ui.INK);p.setTextSize(12);canvas.drawText(names[day],x+col/2,15,p);p.setTextSize(8);canvas.drawText(date.format(DateTimeFormatter.ofPattern("M/d")),x+col/2,30,p);}return bitmap;}
  for(int period=0;period<periods.size();period++){float y=period*ROW_HEIGHT;p.setColor(period%2==0?0xFFF1F5F3:0xFFFAFBFB);canvas.drawRect(axis,y,width,y+ROW_HEIGHT,p);p.setColor(0xFFDEE7E2);p.setStrokeWidth(.5f);canvas.drawLine(axis,y,width,y,p);p.setTextAlign(Paint.Align.CENTER);p.setColor(Ui.INK);p.setTextSize(11);canvas.drawText(String.valueOf(period+1),axis/2,y+13,p);p.setTextSize(7);p.setColor(Ui.MUTED);canvas.drawText(periods.get(period)[0].toString(),axis/2,y+27,p);canvas.drawText(periods.get(period)[1].toString(),axis/2,y+38,p);}
  for(int day=0;day<=7;day++){p.setColor(0xFFE2EAE5);canvas.drawLine(axis+day*col,0,axis+day*col,height,p);}
  List<WeekTable.Item> items=items(c,monday,now);for(WeekTable.Item item:items){float top=Math.max(0,WeekTable.position(item.start,periods)*ROW_HEIGHT),bottom=Math.min(height,Math.max(WeekTable.position(item.start,periods)+.5f,WidgetDayTable.endPosition(item,periods))*ROW_HEIGHT);if(bottom<=top)continue;int peers=1,index=0;for(WeekTable.Item other:items)if(other!=item&&other.day==item.day&&other.start<item.end&&other.end>item.start){peers++;if(other.start<item.start||other.start==item.start&&other.event.optString("id").compareTo(item.event.optString("id"))<0)index++;}float w=col/peers-3,x=axis+item.day*col+index*(col/peers)+1.5f,h=bottom-top-3;p.setColor(WidgetDayTable.color(item,now));canvas.drawRoundRect(new RectF(x,top+1,x+w,bottom-2),4,4,p);int inner=Math.max(1,(int)w-5);TextPaint text=new TextPaint(Paint.ANTI_ALIAS_FLAG);text.setTypeface(c.getResources().getFont(R.font.ui));text.setColor(Ui.INK);text.setTextSize(w>=40?11:10);String name=item.event.optString("title");int maxLines=Math.max(1,Math.min(5,(int)((h-24)/13)));StaticLayout title=StaticLayout.Builder.obtain(name,0,name.length(),text,inner).setIncludePad(false).setMaxLines(maxLines).setEllipsize(TextUtils.TruncateAt.END).build();canvas.save();canvas.clipRect(x+2,top+3,x+w-1,bottom-3);canvas.translate(x+3,top+4);title.draw(canvas);String place=item.event.optString("place");if(!place.isEmpty()&&h-title.getHeight()>18){canvas.translate(0,title.getHeight()+3);text.setTextSize(8);StaticLayout room=StaticLayout.Builder.obtain(place,0,place.length(),text,inner).setIncludePad(false).setMaxLines(Math.min(3,Math.max(1,(int)((h-title.getHeight()-7)/11)))).setEllipsize(TextUtils.TruncateAt.END).build();room.draw(canvas);}canvas.restore();}
  return bitmap;
 }
 static String description(Context c,LocalDate monday,long now){StringBuilder s=new StringBuilder(monday+"至"+monday.plusDays(6)+"周课表");for(WeekTable.Item item:items(c,monday,now))s.append("；周").append(item.day+1).append("，").append(item.event.optString("title")).append("，").append(WidgetData.detail(item,now));return s.toString();}
}
